import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        int[] infected = new int[n];
        for (int i = 0; i < n; i++) infected[i] = nextInt();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < m; i++) {
            int a = nextInt() - 1, b = nextInt() - 1;
            adj.get(a).add(b);
            adj.get(b).add(a);
        }
        int best = n + 1, answer = 0;
        boolean[] seen = new boolean[n];
        int[] queue = new int[n];
        for (int removed = 0; removed < n; removed++) {
            // multi-source BFS from the remaining infected nodes
            Arrays.fill(seen, false);
            seen[removed] = true;
            int head = 0, tail = 0;
            for (int i = 0; i < n; i++)
                if (infected[i] != 0 && i != removed) {
                    seen[i] = true;
                    queue[tail++] = i;
                }
            while (head < tail) {
                int u = queue[head++];
                for (int v : adj.get(u))
                    if (!seen[v]) {
                        seen[v] = true;
                        queue[tail++] = v;
                    }
            }
            if (tail < best) {
                best = tail;
                answer = removed;
            }
        }
        System.out.println(answer + 1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m := int(nextInt()), int(nextInt())
	infected := make([]int64, n)
	for i := range infected {
		infected[i] = nextInt()
	}
	adj := make([][]int, n)
	for i := 0; i < m; i++ {
		a, b := int(nextInt())-1, int(nextInt())-1
		adj[a] = append(adj[a], b)
		adj[b] = append(adj[b], a)
	}
	best, answer := n+1, 0
	seen := make([]bool, n)
	queue := make([]int, n)
	for removed := 0; removed < n; removed++ {
		// multi-source BFS from the remaining infected nodes
		clear(seen)
		seen[removed] = true
		head, tail := 0, 0
		for i := 0; i < n; i++ {
			if infected[i] != 0 && i != removed {
				seen[i] = true
				queue[tail] = i
				tail++
			}
		}
		for head < tail {
			u := queue[head]
			head++
			for _, v := range adj[u] {
				if !seen[v] {
					seen[v] = true
					queue[tail] = v
					tail++
				}
			}
		}
		if tail < best {
			best, answer = tail, removed
		}
	}
	fmt.Println(answer + 1)
}
